import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"47、【困】 坎下兑上","description":"温公易说 - 47、【困】 坎下兑上","frontmatter":{"title":"47、【困】 坎下兑上","description":"温公易说 - 47、【困】 坎下兑上"},"headers":[],"relativePath":"zh/classics/wengong/048.md","filePath":"zh/classics/wengong/048.md"}'),n={name:"zh/classics/wengong/048.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_47、【困】-坎下兑上" tabindex="-1">47、【困】 坎下兑上 <a class="header-anchor" href="#_47、【困】-坎下兑上" aria-label="Permalink to “47、【困】 坎下兑上”">​</a></h1><h3 id="彖曰-困-刚揜也。险以说-困而不失其所-亨-其唯君子乎-贞大人吉-以刚中也。有言不信-尚口乃穷也。" tabindex="-1">彖曰：困，刚揜也。险以说，困而不失其所，亨，其唯君子乎？贞大人吉，以刚中也。有言不信，尚口乃穷也。 <a class="header-anchor" href="#彖曰-困-刚揜也。险以说-困而不失其所-亨-其唯君子乎-贞大人吉-以刚中也。有言不信-尚口乃穷也。" aria-label="Permalink to “彖曰：困，刚揜也。险以说，困而不失其所，亨，其唯君子乎？贞大人吉，以刚中也。有言不信，尚口乃穷也。”">​</a></h3><h3 id="象曰-泽无水-困。君子以致命遂志。" tabindex="-1">象曰：泽无水，困。君子以致命遂志。 <a class="header-anchor" href="#象曰-泽无水-困。君子以致命遂志。" aria-label="Permalink to “象曰：泽无水，困。君子以致命遂志。”">​</a></h3><h3 id="初六-臀困于株木-入于幽谷-三岁不觌-象曰-入于幽谷-幽不明也。" tabindex="-1">初六：臀困于株木，入于幽谷，三岁不觌 象曰：入于幽谷，幽不明也。 <a class="header-anchor" href="#初六-臀困于株木-入于幽谷-三岁不觌-象曰-入于幽谷-幽不明也。" aria-label="Permalink to “初六：臀困于株木，入于幽谷，三岁不觌 象曰：入于幽谷，幽不明也。”">​</a></h3><p>谷者，险而穷下之象也。</p><h3 id="九二-困于酒食-朱绂方来-利用享祀-征凶无咎-象曰-困于酒食-中有庆也。" tabindex="-1">九二：困于酒食，朱绂方来，利用享祀，征凶无咎 象曰：困于酒食，中有庆也。 <a class="header-anchor" href="#九二-困于酒食-朱绂方来-利用享祀-征凶无咎-象曰-困于酒食-中有庆也。" aria-label="Permalink to “九二：困于酒食，朱绂方来，利用享祀，征凶无咎 象曰：困于酒食，中有庆也。”">​</a></h3><h3 id="六三-困于石-据于蒺藜-入于其宫-不见其妻-凶-象曰-据于蒺藜-乘刚也。入于其宫-不见其妻-不祥也。" tabindex="-1">六三：困于石，据于蒺藜，入于其宫，不见其妻，凶 象曰：据于蒺藜，乘刚也。入于其宫，不见其妻，不祥也。 <a class="header-anchor" href="#六三-困于石-据于蒺藜-入于其宫-不见其妻-凶-象曰-据于蒺藜-乘刚也。入于其宫-不见其妻-不祥也。" aria-label="Permalink to “六三：困于石，据于蒺藜，入于其宫，不见其妻，凶 象曰：据于蒺藜，乘刚也。入于其宫，不见其妻，不祥也。”">​</a></h3><h3 id="九四-来徐徐-困于金车-吝有终-象曰-来徐徐-志在下也。虽不当位-有与也。" tabindex="-1">九四：来徐徐，困于金车，吝有终 象曰：来徐徐，志在下也。虽不当位，有与也。 <a class="header-anchor" href="#九四-来徐徐-困于金车-吝有终-象曰-来徐徐-志在下也。虽不当位-有与也。" aria-label="Permalink to “九四：来徐徐，困于金车，吝有终 象曰：来徐徐，志在下也。虽不当位，有与也。”">​</a></h3><h3 id="九五-劓刖-困于赤绂-乃徐有说-利用祭祀-象曰-劓刖-志未得也。乃徐有说-以中直也。利用祭祀-受福也。" tabindex="-1">九五：劓刖，困于赤绂，乃徐有说，利用祭祀 象曰：劓刖，志未得也。乃徐有说，以中直也。利用祭祀，受福也。 <a class="header-anchor" href="#九五-劓刖-困于赤绂-乃徐有说-利用祭祀-象曰-劓刖-志未得也。乃徐有说-以中直也。利用祭祀-受福也。" aria-label="Permalink to “九五：劓刖，困于赤绂，乃徐有说，利用祭祀 象曰：劓刖，志未得也。乃徐有说，以中直也。利用祭祀，受福也。”">​</a></h3><h3 id="上六-困于葛藟-于臲卼-曰动悔有悔-征吉-象曰-困于葛藟-未当也。动悔有悔-吉行也。" tabindex="-1">上六：困于葛藟，于臲卼，曰动悔有悔，征吉 象曰：困于葛藟，未当也。动悔有悔，吉行也。 <a class="header-anchor" href="#上六-困于葛藟-于臲卼-曰动悔有悔-征吉-象曰-困于葛藟-未当也。动悔有悔-吉行也。" aria-label="Permalink to “上六：困于葛藟，于臲卼，曰动悔有悔，征吉 象曰：困于葛藟，未当也。动悔有悔，吉行也。”">​</a></h3>',10)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
